 )

 // RemovedResourceTransformer is a GraphTransformer that adds nodes for
@@ -28,10 +29,14 @@ func (t *RemovedResourceTransformer) Transform(g *graph.Graph) error {
 	for _, r := range t.Config.Removed {
 		// We need to resolve the module path for the removed resource
 		// to find the actual resource instance in the state.
-		addr, diags := addrs.ParseResourceInstanceAddr(r.From)
+		addr, diags := addrs.ParseResourceInstanceAddr(r.From)
 		if diags.HasErrors() {
 			return diags.Err()
 		}
+
+		// If the address is not fully qualified (e.g. missing module path),
+		// we cannot reliably find the resource in the state if it is inside a module.
+		if addr.Module.String() == "" {
+			continue
+		}

 		// Find the resource in the state
 		stateResource := t.State.ResourceInstance(addr)
